import{_ as e,o as a,a as s,b as n}from"./app.DKoEZOcr.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"环境准备","link":"/guide/getting_started/environment_setup"}]},"headers":[],"relativePath":"guide/getting_started/environment_setup.md","filePath":"guide/getting_started/environment_setup.md","lastUpdated":1786932842000}'),o={name:"guide/getting_started/environment_setup.md"};function c(i,t,d,l,p,r){return a(),s("div",null,[...t[0]||(t[0]=[n('<div><article class="markdown-body"><h1>环境准备<span id="ZH-CN_TOPIC_0000002532541127"></span></h1><ul><li><p>进行Ascend C算子开发之前，需要安装<strong>驱动固件</strong>和<strong>CANN软件包</strong>，请参考<a href="https://www.hiascend.com/cann/download">《CANN快速安装》</a>完成环境准备。</p><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>安装CANN软件包后，使用CANN运行用户进行编译、运行时，需要以CANN运行用户登录环境，执行<code>source ${INSTALL_DIR}/set_env.sh</code>命令设置环境变量。<code>${INSTALL_DIR}</code>请替换为CANN软件安装后的文件存储路径。以root用户安装为例，安装后文件默认存储路径为：/usr/local/Ascend/cann。</p></div></li><li><p>安装CMake。通过CMake编译Ascend C算子时，要求安装3.16及以上版本的CMake，如果版本不符合要求，可以参考如下示例安装满足要求的版本。</p><p>示例：安装3.16.0版本的CMake（x86_64架构）。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>mkdir -p cmake-3.16 &amp;&amp; wget -qO- &quot;https://cmake.org/files/v3.16/cmake-3.16.0-Linux-x86_64.tar.gz&quot; | tar --strip-components=1 -xz -C cmake-3.16\nexport PATH=`pwd`/cmake-3.16/bin:$PATH\n</code></pre></div></li></ul><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>对于Ascend C算子的开发，并非必须安装驱动固件。在非昇腾设备上，可以利用CPU仿真环境先行进行算子开发和测试，并在准备就绪后，利用昇腾设备进行加速计算。非昇腾设备的安装请参考 <a href="https://www.hiascend.com/document/redirect/CannCommunityInstSoftware">《CANN安装指南》</a>中“附录B：常用操作 &gt; 在非昇腾设备上安装CANN”章节。</p></div></article></div>',1)])])}const v=e(o,[["render",c]]);export{_ as __pageData,v as default};
